import sys


def dist(a, b):
    if not a:
        return len(b)
    if not b:
        return len(a)
    return min(
        dist(a[1:], b[1:]) + (0 if a[0] == b[0] else 1),
        dist(a[1:], b) + 1,
        dist(a, b[1:]) + 1,
    )


